import {renderDiagram,renderCustomModel}from './visual.js?v=20261023-physicscomplete01';
import {diffusionFrame,diffusionTasks,cubeMeasures,coreFraction,exchangeCases,exchangeOptions,comparedStates}from './diffusion-models.js?v=20261023-physicscomplete01';
import {diffusionFigure,surfaceFigure,exchangeFigure}from './diffusion-figures.js?v=20261023-physicscomplete01';
const opts=(list,value)=>'<option value="">Choose…</option>'+list.map(([v,label])=>`<option value="${v}"${value===v?' selected':''}>${label}</option>`).join('');
export function showDiffusion(kind='gradient',w={}){const f=diffusionFrame({left:w.left??(kind==='equal'?16:kind==='reverse'?8:24),step:w.step,temperature:w.temperature,area:w.area});renderDiagram('Across a membrane',f.step?'Left '+f.left+' · Right '+f.right+' · Step '+f.step:'Equal-volume compartments',diffusionFigure({...f,left:f.initial})+'<p class="diagram-caption">Illustrative particle counts and exchange steps, not measured biological rates. Particles move randomly both ways; snapshots and arrows summarise transfers. The two compartments have equal volumes.</p>','COMPARE NET MOVEMENT');}
export function showSurface(size=1,w={}){const m=cubeMeasures(Number(size)),depth=(Number(w.depth)||0)*.125,core=Math.max(0,m.side-2*depth);renderCustomModel({name:'Surface area & volume',formula:w.revealed?'SA:V = '+m.ratio+':1':'Cube edge '+m.side+' units',kicker:'SCHEMATIC CUBE · SAME DIFFUSION DEPTH',atoms:[],bonds:[],radius:3,viewKey:'surface-cube',startPaused:true,note:'Shape model · no biological time scale',aria:'Cube edge '+m.side+' units. Coral marks outer layer reached to depth '+depth+' units. Dark core is unreached. Rotate with arrow keys.',diagram:surfaceFigure(m.side,depth)+`<p class="diagram-caption">Same illustrative penetration depth ${depth} units; unreached core ${Math.round(coreFraction(m.side,depth)*100)}%. This is a geometry comparison, not a living cell or measured diffusion rate.</p>`,build:(g,T)=>{const scale=.85,outer=new T.Mesh(new T.BoxGeometry(m.side*scale,m.side*scale,m.side*scale),new T.MeshStandardMaterial({color:0xed8b78,transparent:true,opacity:depth? .3:.12,roughness:.25,depthWrite:false}));g.add(outer);const edges=new T.LineSegments(new T.EdgesGeometry(outer.geometry),new T.LineBasicMaterial({color:0xf8f6f2}));g.add(edges);if(core>0){const inner=new T.Mesh(new T.BoxGeometry(core*scale,core*scale,core*scale),new T.MeshStandardMaterial({color:0x526f86,roughness:.35,metalness:.08}));g.add(inner);}}});}
export function showExchange(id='lungs',w={}){const c=exchangeCases.find(c=>c.id===id)||exchangeCases[0],adapted=w.adapted!==false;renderDiagram(c.name,adapted?c.featureName+' present':c.featureName+' removed',exchangeFigure(c.id,adapted)+`<p class="diagram-caption">${adapted?c.on:c.off} Schematic comparison, not organ anatomy or a measured rate. Other conditions are held constant; removal is a counterfactual.</p>`,'CONNECT STRUCTURE TO EXCHANGE');}
export function mountDiffusion(l,p,root,{save,done,feedback}){const w=p.widget,$=s=>root.querySelector(s);w.task??=0;w.passed??=[];const total=l.widget==='surface-lab'?3:5,task=w.task%total;const tail='<button class="secondary" id="checkTransport">Check reasoning</button><button class="secondary" id="nextTransport">Next challenge →</button><p id="transportProgress">'+w.passed.length+' / '+total+' complete</p>';const finish=()=>{if(!w.passed.includes(task))w.passed.push(task);if(w.passed.length===total){p.widgetDone=true;save();done();}save();$('#transportProgress').textContent=w.passed.length+' / '+total+' complete';};
if(l.widget==='diffusion-lab'){const t=diffusionTasks[task];w.diffRecords??={};const r=w.diffRecords[t.id]??={step:0,temperature:1,area:1,runs:[]};const factor=t.id==='temperature'?'temperature':t.id==='area'?'area':null;root.innerHTML=`<p><b>${task+1} / 5 · ${t.title}</b></p><p>Start: left ${t.left}, right ${32-t.left} particles, equal volumes. ${factor?'Compare setting1 and2 from the same starting state.':'Track movement in both directions.'}</p><label class="field-label" for="diffPrediction">Predict</label><select class="lab-select" id="diffPrediction">${opts(t.options,r.answer)}</select>${factor?'<label class="field-label" for="diffFactor">'+(factor==='temperature'?'Temperature':'Membrane area')+'</label><select class="lab-select" id="diffFactor">'+opts([['1',factor==='temperature'?'Lower temperature':'Smaller area'],['2',factor==='temperature'?'Higher temperature':'Larger area']],String(r[factor]))+'</select>':''}<button class="secondary" id="stepDiffusion">Step particle exchange →</button><button class="secondary" id="resetDiffusion">Reset this comparison</button><p id="diffReadout" aria-live="polite"></p>`+tail;
const draw=()=>{const f=diffusionFrame({left:t.left,...r});showDiffusion(t.id,{left:t.left,...r});$('#diffReadout').textContent='Step '+r.step+': left '+f.left+', right '+f.right+'. Last step: '+f.lr+' → and '+f.rl+' ←. No respiration energy is used for diffusion.'+(factor?' First-step comparison (left remaining): lower/smaller '+(r.firstCounts?.['1']??'not tested')+'; higher/larger '+(r.firstCounts?.['2']??'not tested')+'.':'');};$('#diffPrediction').onchange=e=>{r.answer=e.target.value;save();};$('#stepDiffusion').onclick=()=>{if(!r.answer){feedback('Predict before stepping the particles.',true);return;}r.step=Math.min(12,r.step+1);const key=String(factor?r[factor]:1);if(!r.runs.includes(key))r.runs.push(key);r.firstCounts??={};if(r.step===1)r.firstCounts[key]=diffusionFrame({left:t.left,...r}).left;save();draw();};$('#resetDiffusion').onclick=()=>{r.step=0;save();draw();};if(factor)$('#diffFactor').onchange=e=>{r[factor]=Number(e.target.value)||1;r.step=0;save();draw();};$('#checkTransport').onclick=()=>{if(!r.runs.includes('1')||(factor&&!r.runs.includes('2'))){feedback('Run each requested condition after predicting. Resetting keeps your comparison record.',true);return;}if(r.answer!==t.answer){feedback(t.why,true);return;}feedback(t.why);finish();};draw();
}else if(l.widget==='surface-lab'){const side=[1,2,4][task],m=cubeMeasures(side);w.surfaceRecords??={};w.size??=side;w.depth??=0;w.depthSeen??=[w.depth];const r=w.surfaceRecords[side]??={};root.innerHTML=`<p><b>${task+1} / 3 · Cube edge ${side} units</b></p><p>Calculate this cube’s surface area, volume and SA:V as x:1. Compare the size and reached outer layer using the model.</p><label class="field-label" for="cubeSize">Model cube edge</label><select class="lab-select" id="cubeSize">${opts([['1','1 unit'],['2','2 units'],['4','4 units']],String(w.size))}</select><label class="field-label" for="cubeDepth">Illustrative penetration depth</label><input id="cubeDepth" type="range" min="0" max="2" step="1" value="${w.depth}"><p class="micro-note" id="coreReadout"></p>${[['surface','Surface area (square units)'],['volume','Volume (cubic units)'],['ratio','SA:V, x in x:1']].map(([key,label])=>`<label class="field-label" for="cube-${key}">${label}</label><input class="lab-input" id="cube-${key}" type="number" step="any" value="${r[key]??''}">`).join('')}${task===2?'<label class="field-label" for="sizeReason">Why do large multicellular organisms need specialised exchange and transport?</label><select id="sizeReason" class="lab-select">'+opts([['low','Lower SA:V; longer paths'],['high','They have higher SA:V'],['none','Their cells need no exchange']],r.reason)+'</select>':''}`+tail;
const draw=()=>{showSurface(w.size,w);$('#coreReadout').textContent='Depth '+(w.depth*.125)+' units · unreached core '+Math.round(coreFraction(w.size,w.depth*.125)*100)+'%. Same depth at every cube size.';};$('#cubeSize').onchange=e=>{w.size=Number(e.target.value)||1;w.revealed=false;w.sizesSeen??=[];if(!w.sizesSeen.includes(w.size))w.sizesSeen.push(w.size);save();draw();};$('#cubeDepth').oninput=e=>{w.depth=Number(e.target.value);w.depthSeen??=[];if(!w.depthSeen.includes(w.depth))w.depthSeen.push(w.depth);save();draw();};for(const key of['surface','volume','ratio'])$('#cube-'+key).oninput=e=>{r[key]=e.target.value;save();};if(task===2)$('#sizeReason').onchange=e=>{r.reason=e.target.value;save();};$('#checkTransport').onclick=()=>{if(w.size!==side){feedback('Set the model cube edge to '+side+' units for this challenge.',true);return;}if(['surface','volume','ratio'].some(key=>String(r[key]??'').trim()===''||Math.abs(Number(r[key])-m[key])>.001)){feedback('Use6 × edge² for the six faces and edge³ for volume. Divide surface area by volume to find x in x:1.',true);return;}if(task===2&&(!w.depthSeen?.includes(0)||!w.depthSeen?.includes(2)||r.reason!=='low')){feedback('Compare depth0 and0.25 using the slider, then explain the lower ratio and longer paths of a larger organism.',true);return;}w.revealed=true;save();draw();feedback('Surface '+m.surface+', volume '+m.volume+', SA:V '+m.ratio+':1. As edge length increases, volume grows faster than surface area.');finish();};draw();
}else{const c=exchangeCases[task];w.exchangeRecords??={};const r=w.exchangeRecords[c.id]??={adapted:true,states:[]};root.innerHTML=`<p><b>${task+1} / 5 · ${c.name}</b></p><p>${c.detail}</p><label class="field-label" for="exchangePrediction">Predict the feature’s main benefit</label><select class="lab-select" id="exchangePrediction">${opts(exchangeOptions,r.answer)}</select><button class="secondary" id="toggleExchange">${r.adapted?'Remove':'Restore'}: ${c.featureName}</button><button class="secondary" id="observeExchange">Observe this state</button><p id="exchangeReadout" aria-live="polite"></p>`+tail;
const draw=()=>{showExchange(c.id,r);$('#toggleExchange').textContent=(r.adapted?'Remove: ':'Restore: ')+c.featureName;$('#exchangeReadout').textContent=r.adapted?c.on:c.off;};$('#exchangePrediction').onchange=e=>{r.answer=e.target.value;save();};$('#toggleExchange').onclick=()=>{if(!r.answer){feedback('Make a prediction before changing the structure.',true);return;}r.adapted=!r.adapted;save();draw();};$('#observeExchange').onclick=()=>{if(!r.answer){feedback('Predict first, then observe the comparison.',true);return;}const state=r.adapted?'on':'off';if(!r.states.includes(state))r.states.push(state);save();feedback('State recorded. Compare the feature present and removed.');};$('#checkTransport').onclick=()=>{if(!comparedStates(r.states)){feedback('Observe both the present and removed states after making your prediction.',true);return;}if(r.answer!==c.effect){feedback(c.featureName+' helps through '+({area:'increased exchange area',path:'a shorter diffusion path',gradient:'maintaining a concentration gradient'}[c.effect])+'. Diffusion does not require energy from respiration.',true);return;}feedback(c.on);finish();};draw();}
$('#nextTransport').onclick=()=>{if(!w.passed.includes(task)){feedback('Complete this challenge first.',true);return;}w.task=(task+1)%total;if(l.widget==='surface-lab'){w.size=[1,2,4][w.task];w.revealed=false;}save();feedback('');mountDiffusion(l,p,root,{save,done,feedback});};}
